  "Owner": "\u0627\u0644\u0645\u0627\u0644\u0643",
  "Full control, billing and publishing.": "\u062A\u062D\u0643\u0645 \u0643\u0627\u0645\u0644 \u0648\u0627\u0644\u0641\u0648\u062A\u0631\u0629 \u0648\u0627\u0644\u0646\u0634\u0631.",
  "Manage members and shared projects.": "\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u0629.",
  "Edit shared project content.": "\u062A\u0639\u062F\u064A\u0644 \u0645\u062D\u062A\u0648\u0649 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u0629.",
  "Read-only access.": "\u0635\u0644\u0627\u062D\u064A\u0629 \u0639\u0631\u0636 \u0641\u0642\u0637.",
  "Unexpected error": "\u062E\u0637\u0623 \u063A\u064A\u0631 \u0645\u062A\u0648\u0642\u0639",
