  "Health": "\u0627\u0644\u062D\u0627\u0644\u0629",
  "Sync": "\u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629",
  "Live": "\u0645\u0628\u0627\u0634\u0631",
