  "These checks involve external services and must be confirmed by a human before accepting paid customers.": "\u062A\u062A\u0636\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0641\u062D\u0648\u0635\u0627\u062A \u062E\u062F\u0645\u0627\u062A \u062E\u0627\u0631\u062C\u064A\u0629 \u0648\u064A\u062C\u0628 \u062A\u0623\u0643\u064A\u062F\u0647\u0627 \u064A\u062F\u0648\u064A\u0627\u064B \u0642\u0628\u0644 \u0627\u0633\u062A\u0642\u0628\u0627\u0644 \u0639\u0645\u0644\u0627\u0621 \u0645\u062F\u0641\u0648\u0639\u064A\u0646.",
  "Release actions": "\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0627\u0644\u0625\u0635\u062F\u0627\u0631",
