  "Audit & backups": "\u0627\u0644\u062A\u062F\u0642\u064A\u0642 \u0648\u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629",
  "Export backup and diagnostics": "\u062A\u0635\u062F\u064A\u0631 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629 \u0648\u0627\u0644\u062A\u0634\u062E\u064A\u0635\u0627\u062A",
  "Blocked until automated preflight is ready": "\u0645\u062D\u0638\u0648\u0631 \u062D\u062A\u0649 \u062A\u062C\u0647\u0632 \u0641\u062D\u0648\u0635\u0627\u062A \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0625\u0637\u0644\u0627\u0642",
