  "Use the exact Gemini API model ID, for example gemini-3.x-flash.": "\u0627\u0633\u062A\u062E\u062F\u0645 \u0645\u0639\u0631\u0651\u0641 \u0646\u0645\u0648\u0630\u062C Gemini API \u0627\u0644\u062F\u0642\u064A\u0642\u060C \u0645\u062B\u0644 gemini-3.x-flash.",
  "Display name (optional)": "\u0627\u0633\u0645 \u0627\u0644\u0639\u0631\u0636 (\u0627\u062E\u062A\u064A\u0627\u0631\u064A)",
