  "Grammar": "\u0627\u0644\u0642\u0648\u0627\u0639\u062F",
  "Complete": "\u0627\u0644\u0627\u0643\u062A\u0645\u0627\u0644",
  "Prof.": "\u0627\u0644\u0627\u062D\u062A\u0631\u0627\u0641\u064A\u0629",
  "Readable": "\u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629",
  "Overall": "\u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A",
  "Loading Tayar Intelligence\u2026": "\u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 Tayar Intelligence\u2026",
  "Account suspended": "\u0627\u0644\u062D\u0633\u0627\u0628 \u0645\u0648\u0642\u0648\u0641",
